import styled from "styled-components";


export const BodyRegisterContainer= styled.div`
  
    width: 100%;
    display:flex;
    align-items:center;
    justify-content: center;
    
`

export const CardRegisterContainer = styled.div`  
    width:25%;
    height:25rem;
    position: absolute;
    box-shadow: 5px 4px 6px rgba(0,0,0,0.25);
    margin-top: 40%;
    border-radius: 20px;

`

export const InputRegisterContainer = styled.div`
    width:100%;
    height: 50%;

    background: ${({theme}) => theme.colors.background};
    border:1px solid ${({theme}) => theme.colors.primary};
    border-radius: 10px;
    margin-bottom: 20px;

    display:flex;
    justify-content: center;
    z-index: 5000;

    input{
        font-size: 0.75rem;
        font-weight: 400;
        background: transparent;
        border: 0;
        width: 100%;
        margin: 0 20px;
    }
`
